WITH ranked AS MATERIALIZED(SELECT pb.id_user,RANK() OVER(PARTITION BY pb.id_level ORDER BY record.time) placement_rank,COUNT(*) OVER(PARTITION BY pb.id_level) field_count FROM (SELECT * FROM public.personal_best_global WHERE record_eligible) pb JOIN (SELECT * FROM public.record WHERE record_eligible) record ON record.id=pb.id_record JOIN public."user" account ON account.id=pb.id_user WHERE account.banned=false AND record.time>0),eligible AS(SELECT id_user,1-(placement_rank-1)::double precision/(field_count-1) placement FROM ranked WHERE field_count>=20),placements AS(SELECT id_user,sum(placement)::double precision placement_sum,count(*)::integer eligible_level_count FROM eligible GROUP BY id_user) INSERT INTO public.player_skill_aggregate(id_user,placement_sum,eligible_level_count,skill,date_updated) SELECT id_user,placement_sum,eligible_level_count,(5.0+placement_sum)/(10+eligible_level_count),clock_timestamp() FROM placements
